package operators;

public class Classwork {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//POSTFIX
		int A=20;
		int value=A++;
		System.out.println("value="+value+"\t"+"A="+A);
		
		//PREFIX
		int value1=++A;
		System.out.println("value="+value1+"\t"+"A="+A);
		
		//decrement
		//POSTFIX
		int value2=A--;
		System.out.println("value="+value2+"\t"+"A="+A);
		
		//PREFIX
		int value3=--A;
		System.out.println("value="+value3+"\t"+"A="+A);
		
		


	}

}
